<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kullanıcı yönetimi</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1100px;margin:35px auto;padding:0 18px}table{width:100%;border-collapse:collapse;background:white;border-radius:14px;overflow:hidden}td,th{text-align:left;padding:13px;border-bottom:1px solid #edf0ed;font-size:14px}button{border:0;background:#176b50;color:white;padding:9px 12px;border-radius:8px;font-weight:700}.muted{color:#6d796f;font-size:12px}</style></head><body><main class="wrap"><h1>Kullanıcılar</h1><table><thead><tr><th>Kullanıcı</th><th>E-posta</th><th>Rol</th><th>Durum</th><th>Kayıt</th><th></th></tr></thead><tbody><?php foreach($users as $account): ?><tr><td><?= e($account['username']) ?></td><td><?= e($account['email']) ?></td><td><?= e($account['role']) ?></td><td><?= e($account['status']) ?></td><td class="muted"><?= e($account['created_at']) ?></td><td><?php if((int)$account['id']!==(int)$currentUser['id'] && $account['role']!=='super_admin'): ?><form method="post" action="/admin/users/status"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$account['id'] ?>"><input type="hidden" name="status" value="<?= $account['status']==='active'?'disabled':'active' ?>"><button><?= $account['status']==='active'?'Devre dışı bırak':'Etkinleştir' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><p><a href="/admin">Yönetim paneli</a></p></main></body></html>